import { useEffect, useState } from "react";
import { motion, AnimatePresence, useReducedMotion } from "motion/react";
import { Flame } from "lucide-react";
import type { AppHandle } from "@app/kit/primitives";

const HERO = "https://images.unsplash.com/photo-1414235077428-338989a2e8c0?auto=format&fit=crop&w=2000&q=75";
const serif = { fontFamily: "'Iowan Old Style','Palatino Linotype',Palatino,'Book Antiqua',Georgia,serif" } as const;
const EASE = [0.22, 1, 0.36, 1] as const;
const DAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];

const GMark = () => (
  <svg width="18" height="18" viewBox="0 0 48 48" aria-hidden="true">
    <path fill="#EA4335" d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z" />
    <path fill="#4285F4" d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z" />
    <path fill="#FBBC05" d="M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z" />
    <path fill="#34A853" d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z" />
  </svg>
);

export default function TableforLogin({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [hours, setHours] = useState<Record<string, unknown>[]>([]);
  const [dayName, setDayName] = useState("");

  const up = app?.auth.mode === "signup";
  const providers = app?.auth.providers ?? [];
  const canSignUp = app?.auth.canSignUp ?? true;

  useEffect(() => {
    setDayName(DAYS[new Date().getDay()]);
    if (!app) return;
    app.query("opening_hour", { limit: 7 }).then((r) => setHours(r.rows)).catch(() => undefined);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  const todayHours = hours.find((h) => String(h.day) === dayName);
  const openLine = todayHours
    ? String(todayHours.opens) === "Closed"
      ? "Closed today, back tomorrow"
      : `Open today ${String(todayHours.opens)}–${String(todayHours.closes)}`
    : "";

  const submit = async () => {
    if (!app || busy) return;
    if (!email.trim() || !password) {
      setErr("Enter your email and password to continue.");
      return;
    }
    setBusy(true);
    setErr("");
    try {
      if (!up) await app.auth.signIn(email.trim(), password);
      else await app.auth.signUp({ name: name.trim() || email.split("@")[0], email: email.trim(), password });
    } catch (e) {
      setErr(e instanceof Error ? e.message : "That didn't work. Check your details and try again.");
    } finally {
      setBusy(false);
    }
  };

  const provider = async (p: string) => {
    setErr("");
    try {
      await app?.auth.startProvider(p);
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Couldn't start that sign-in. Please try again.");
    }
  };

  const flip = () => {
    app?.auth.setMode(up ? "login" : "signup");
    setErr("");
  };

  const input =
    "h-12 w-full rounded-xl border border-white/20 bg-white/[0.06] px-4 text-base text-white placeholder:text-white/60 outline-none transition-colors duration-200 focus:border-[#F08A6C] focus:bg-white/10 focus-visible:ring-2 focus-visible:ring-[#F08A6C]/50";
  const label = "mb-1.5 block text-sm font-medium text-white/85";

  return (
    <div className="relative min-h-[100dvh] w-full overflow-hidden bg-[#141312] text-white selection:bg-[#E2552E]/40">
      <motion.img
        src={HERO}
        alt=""
        className="absolute inset-0 h-full w-full object-cover"
        initial={reduce ? false : { scale: 1.04, opacity: 0.6 }}
        animate={{ scale: 1, opacity: 1 }}
        transition={{ duration: 1.2, ease: EASE }}
      />
      <div className="absolute inset-0 bg-[#141312]/60" />
      <div className="absolute inset-0 bg-gradient-to-t from-[#141312] via-[#141312]/40 to-transparent" />

      <header className="absolute inset-x-0 top-0 flex items-start justify-between gap-6 px-5 pt-5 lg:px-14 lg:pt-12">
        <div className="flex items-center gap-2.5 lg:invisible">
          <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#B4401C] text-white">
            <Flame size={20} strokeWidth={2} aria-hidden="true" />
          </span>
          <span className="text-2xl tracking-[-0.01em]" style={serif}>
            Tablefor
          </span>
        </div>
        <p className="hidden max-w-xs text-right text-[15px] leading-snug text-white/90 lg:block">
          <span className="block text-lg italic" style={serif}>
            Fig &amp; Ember, Old Market
          </span>
          <span className="mt-1 block text-white/75">Wood-fired plates and late tables{openLine ? ` · ${openLine}` : ""}</span>
        </p>
      </header>

      <div className="relative flex min-h-[100dvh] items-end lg:items-center lg:px-14">
        <motion.main
          className="w-full rounded-t-3xl border-t border-white/10 bg-[#1C1A18] px-5 pb-8 pt-7 sm:mx-auto sm:max-w-md sm:rounded-3xl sm:border lg:mx-0 lg:w-[28rem] lg:p-9"
          initial={reduce ? false : { y: 24, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          transition={{ duration: 0.5, ease: EASE, delay: 0.1 }}
          aria-labelledby="tf-title"
        >
          <div className="mb-7 hidden items-center gap-2.5 lg:flex">
            <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#B4401C] text-white">
              <Flame size={20} strokeWidth={2} aria-hidden="true" />
            </span>
            <span className="text-2xl tracking-[-0.01em]" style={serif}>Tablefor</span>
          </div>
          <h1 id="tf-title" className="text-[2rem] leading-[1.1] tracking-[-0.015em] lg:text-[2.25rem]" style={serif}>
            {up ? "Pull up a chair." : "Your table is waiting."}
          </h1>
          <p className="mt-2 text-[15px] leading-relaxed text-white/80">
            {up ? "Create an account to book tables and keep your door passes in one place." : "Sign in to book a table, find your door pass, or run tonight's service."}
          </p>
          {openLine && <p className="mt-2 text-sm text-white/75 lg:hidden">{openLine}</p>}

          <form
            className="mt-6 space-y-4"
            onSubmit={(e) => {
              e.preventDefault();
              void submit();
            }}
          >
            <AnimatePresence initial={false}>
              {up && (
                <motion.div
                  key="name"
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: "auto" }}
                  exit={{ opacity: 0, height: 0 }}
                  transition={{ duration: 0.2, ease: EASE }}
                  className="overflow-hidden"
                >
                  <label htmlFor="tf-name" className={label}>
                    Name
                  </label>
                  <input id="tf-name" autoComplete="name" className={input} value={name} onChange={(e) => setName(e.target.value)} placeholder="As it should appear on your booking" />
                </motion.div>
              )}
            </AnimatePresence>
            <div>
              <label htmlFor="tf-email" className={label}>
                Email
              </label>
              <input id="tf-email" aria-label="Email" type="email" autoComplete="email" className={input} value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@example.com" />
            </div>
            <div>
              <label htmlFor="tf-pass" className={label}>
                Password
              </label>
              <input
                id="tf-pass"
                aria-label="Password"
                type="password"
                autoComplete={up ? "new-password" : "current-password"}
                className={input}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder={up ? "At least 8 characters" : "Your password"}
              />
            </div>

            <AnimatePresence>
              {err && (
                <motion.p
                  role="alert"
                  initial={{ opacity: 0, y: -4 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0 }}
                  transition={{ duration: 0.2, ease: EASE }}
                  className="rounded-xl border border-[#F08A6C]/40 bg-[#F08A6C]/10 px-3.5 py-2.5 text-sm text-[#FFD9CC]"
                >
                  {err}
                </motion.p>
              )}
            </AnimatePresence>

            <button
              type="submit"
              disabled={busy}
              className="flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-[#B4401C] px-5 text-base font-semibold text-white transition-colors duration-200 hover:bg-[#9C3615] active:scale-[0.99] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/70 disabled:opacity-70"
            >
              {busy && <span aria-hidden="true" className="h-4 w-4 animate-spin rounded-full border-2 border-white/40 border-t-white" />}
              {busy ? (up ? "Creating account…" : "Signing in…") : up ? "Create account" : "Sign in"}
            </button>
          </form>

          {providers.length > 0 && (
            <>
              <div className="my-5 flex items-center gap-3 text-sm text-white/70">
                <span className="h-px flex-1 bg-white/15" />
                or
                <span className="h-px flex-1 bg-white/15" />
              </div>
              <div className="space-y-2.5">
                {providers.map((p) => (
                  <button
                    key={p.name}
                    type="button"
                    onClick={() => void provider(p.name)}
                    className="flex h-12 w-full items-center justify-center gap-3 rounded-xl bg-white px-5 text-base font-semibold text-[#1D2023] transition-colors duration-200 hover:bg-[#F1F1EE] active:scale-[0.99] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#F08A6C]"
                  >
                    {p.name === "google" && <GMark />}
                    Continue with {p.label}
                  </button>
                ))}
              </div>
            </>
          )}

          {canSignUp && (
            <p className="mt-5 text-center text-[15px] text-white/80">
              {up ? "Already have an account? " : "First time here? "}
              <button type="button" onClick={flip} className="min-h-11 font-semibold text-white underline decoration-white/40 underline-offset-4 hover:decoration-white">
                {up ? "Sign in" : "Create an account"}
              </button>
            </p>
          )}
        </motion.main>
      </div>
    </div>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { AnimatePresence, motion, useReducedMotion } from 'motion/react';
import { QRCodeSVG } from 'qrcode.react';
import { Sparkles, CalendarDays, Flame, LogOut, Plus, QrCode, Utensils, X, Check, MapPin, Phone, AlertCircle, ChevronDown } from 'lucide-react';
import type { AppHandle } from '@app/kit/primitives';

type R = Record<string, unknown>;
type Tab = 'home' | 'book' | 'mine';

const serif = { fontFamily: "'Iowan Old Style','Palatino Linotype',Palatino,'Book Antiqua',Georgia,serif" } as const;
const EASE = [0.22, 1, 0.36, 1] as const;
const HERO = 'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?auto=format&fit=crop&w=1800&q=75';
const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const CATS = ['starter', 'main', 'dessert', 'drink'];
const CAT_LABEL: Record<string, string> = { starter: 'Starters', main: 'Mains', dessert: 'Desserts', drink: 'Drinks' };
const STATUS: Record<string, { label: string; cls: string }> = {
booked: { label: 'Confirmed', cls: 'bg-[#FBEDE8] text-[#9C3615]' },
seated: { label: 'Seated', cls: 'bg-[#E3F1E8] text-[#1F6B43]' },
done: { label: 'Visited', cls: 'bg-[#EEEEEA] text-[#50565D]' },
no_show: { label: 'Missed', cls: 'bg-[#FBF0DC] text-[#7A4E00]' },
cancelled: { label: 'Cancelled', cls: 'bg-[#EEEEEA] text-[#50565D]' },
};
const IDEAS = ['Vegetarian, nothing too spicy', 'Something to share for four', 'Light and gluten-free'];

const s = (v: unknown) => String(v ?? '');
const n = (v: unknown) => Number(v) || 0;
const ymd = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
const parse = (iso: string) => {
const [y, m, d] = iso.slice(0, 10).split('-').map(Number);
return new Date(y || 2000, (m || 1) - 1, d || 1);
};
const nice = (iso: string) => {
const d = parse(iso);
return `${DAYS[d.getDay()].slice(0, 3)} ${d.getDate()} ${MONTHS[d.getMonth()]}`;
};
const mins = (t: string) => n(t.slice(0, 2)) * 60 + n(t.slice(3, 5));
const tableName = (t: unknown) => `Table ${s(t).replace(/^T/, '')}`;
const guests = (p: unknown) => `${n(p)} ${n(p) === 1 ? 'guest' : 'guests'}`;
const makeCode = () => {
const al = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
let c = 'FE-';
for (let i = 0; i < 4; i++) c += al[Math.floor(Math.random() * al.length)];
return c;
};

const primary = 'inline-flex h-12 items-center justify-center gap-2 whitespace-nowrap rounded-xl bg-[#B4401C] px-6 text-[15px] font-semibold text-white transition-colors duration-200 hover:bg-[#9C3615] active:scale-[0.99] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#B4401C] focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:bg-[#DCDCD7] disabled:text-[#50565D]';
const ghost = 'inline-flex h-11 items-center justify-center gap-2 rounded-xl border border-[#D6D6D0] bg-white px-5 text-[15px] font-medium text-[#1D2023] transition-colors duration-200 hover:bg-[#F0F0EC] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#B4401C]';
const h2cls = 'text-[17px] font-semibold text-[#1D2023] ![font-family:inherit]';
const field = 'h-12 w-full min-w-0 rounded-xl border border-[#D6D6D0] bg-white px-4 text-base text-[#1D2023] outline-none placeholder:text-[#6B7178] focus:border-[#B4401C] focus-visible:ring-2 focus-visible:ring-[#B4401C]/25';
const muted = 'text-[#50565D]';

function Bar() {
return <span aria-hidden='true' className='block h-0.5 w-3.5 rounded bg-current' />;
}

function DishRow({ d, why }: { d: R; why?: string }) {
return (
<div className='flex gap-4 py-4'>
<img src={s(d.photo)} alt={s(d.name)} loading='lazy' className='h-20 w-20 shrink-0 rounded-xl bg-[#E9E9E4] object-cover sm:h-24 sm:w-24' />
<div className='min-w-0 flex-1'>
<div className='flex items-baseline justify-between gap-3'>
<h4 className='text-[19px] leading-snug text-[#1D2023]' style={serif}>{s(d.name)}</h4>
<span className='shrink-0 text-[15px] font-semibold tabular-nums text-[#1D2023]'>${n(d.price)}</span>
</div>
<p className={`mt-1 text-[15px] leading-relaxed ${muted}`}>{why || s(d.description)}</p>
{s(d.tags) && !why && <span className={`mt-2 inline-block rounded-full bg-[#EEEEEA] px-2.5 py-0.5 text-[13px] font-medium ${muted}`}>{s(d.tags)}</span>}
</div>
</div>
);
}

function RowSkeleton() {
return (
<div className='flex gap-4 py-4'>
<div className='h-20 w-20 shrink-0 animate-pulse rounded-xl bg-[#E9E9E4]' />
<div className='flex-1 space-y-2.5 pt-1'>
<div className='h-4 w-1/2 animate-pulse rounded bg-[#E9E9E4]' />
<div className='h-3.5 w-4/5 animate-pulse rounded bg-[#E9E9E4]' />
</div>
</div>
);
}

function AskMenu({ app, dishes }: { app?: AppHandle; dishes: R[] }) {
const reduce = useReducedMotion();
const [q, setQ] = useState('');
const [asked, setAsked] = useState('');
const [busy, setBusy] = useState(false);
const [picks, setPicks] = useState<{ d: R; why: string }[]>([]);
const [msg, setMsg] = useState<{ kind: 'empty' | 'err'; text: string } | null>(null);
const ask = async (text?: string) => {
const query = (text ?? q).trim();
if (!app || !query || busy) return;
if (text) setQ(text);
if (!dishes.length) {
setMsg({ kind: 'err', text: 'The menu is still loading. Try again in a moment.' });
return;
}
setBusy(true);
setMsg(null);
setPicks([]);
setAsked(query);
try {
const menu = dishes.map((d) => `${s(d.name)} | ${s(d.category)} | ${s(d.tags)} | ${s(d.description)}`).join('\n');
const out = await app.ai.ask(`Menu (name | course | tags | description):\n${menu}\n\nGuest: ${query.slice(0, 200)}\nPick 2-3 dishes from the menu only. JSON only: [{"name":"exact name","why":"one short sentence, under 18 words"}]`, { system: "You are the maitre d' of Fig & Ember. Recommend only listed dishes, respect dietary needs strictly, reply with JSON only.", maxTokens: 400 });
const m = out.match(/\[[\s\S]*\]/);
const arr = JSON.parse(m ? m[0] : '[]') as { name?: string; why?: string }[];
const found: { d: R; why: string }[] = [];
for (const a of arr) {
const d = dishes.find((x) => s(x.name).toLowerCase() === s(a.name).toLowerCase());
if (d && !found.some((f) => f.d === d)) found.push({ d, why: s(a.why) });
}
if (!found.length) setMsg({ kind: 'empty', text: "Nothing on tonight's menu fits that. Try describing it another way." });
setPicks(found.slice(0, 3));
} catch {
setMsg({ kind: 'err', text: 'The menu assistant is unavailable right now. Browse the menu below, or ask your server at the table.' });
} finally {
setBusy(false);
}
};
return (
<section className='mx-auto max-w-6xl px-4 pt-10 lg:px-8 lg:pt-14' aria-labelledby='ask-title'>
<div className='grid gap-6 rounded-2xl border border-[#E3E3DE] bg-white p-5 sm:p-8 lg:grid-cols-[19rem_1fr] lg:gap-12'>
<div>
<span className='flex h-10 w-10 items-center justify-center rounded-xl bg-[#FBEDE8] text-[#B4401C]'><Sparkles size={20} aria-hidden='true' /></span>
<h2 id='ask-title' className='mt-4 text-[28px] leading-tight tracking-[-0.01em] text-[#1D2023]' style={serif}>Not sure what to order?</h2>
<p className={`mt-2 text-[15px] leading-relaxed ${muted}`}>Tell us what you feel like, or what you can't eat. We'll pick two or three plates from tonight's menu.</p>
</div>
<div className='min-w-0'>
<form onSubmit={(e) => { e.preventDefault(); void ask(); }} className='flex flex-col gap-2 sm:flex-row'>
<label htmlFor='ask-q' className='sr-only'>What are you in the mood for?</label>
<input id='ask-q' value={q} onChange={(e) => setQ(e.target.value)} placeholder='e.g. vegetarian, not too rich' className={`${field} sm:flex-1`} />
<button type='submit' disabled={busy || !q.trim()} className={primary}>{busy ? 'Thinking…' : 'Suggest dishes'}</button>
</form>
<div className='mt-3 flex flex-wrap gap-2'>
{IDEAS.map((i) => (
<button key={i} type='button' disabled={busy} onClick={() => void ask(i)} className='min-h-11 rounded-full border border-[#E3E3DE] bg-[#F5F5F3] px-4 text-sm text-[#3A3F45] transition-colors duration-200 hover:border-[#B4401C] hover:text-[#9C3615] disabled:opacity-60'>{i}</button>
))}
</div>
<div aria-live='polite'>
{busy && (
<div className='mt-2 divide-y divide-[#EEEEEA]'>
<RowSkeleton />
<RowSkeleton />
<p className={`pt-3 text-sm ${muted}`}>Reading tonight's menu…</p>
</div>
)}
{msg && !busy && (
<p className={`mt-4 flex items-start gap-2.5 rounded-xl px-4 py-3 text-[15px] ${msg.kind === 'err' ? 'border border-[#F0C9BC] bg-[#FDF3EF] text-[#7E2E12]' : `bg-[#F5F5F3] ${muted}`}`}>
<AlertCircle size={18} className='mt-0.5 shrink-0' aria-hidden='true' />
{msg.text}
</p>
)}
{picks.length > 0 && !busy && (
<div className='mt-4'>
<p className={`text-sm font-medium ${muted}`}>Our picks for “{asked}”</p>
<div className='divide-y divide-[#EEEEEA]'>
{picks.map((p, i) => (
<motion.div key={s(p.d.id)} initial={reduce ? false : { opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.25, ease: EASE, delay: i * 0.06 }}>
<DishRow d={p.d} why={p.why} />
</motion.div>
))}
</div>
</div>
)}
</div>
</div>
</div>
</section>
);
}

export default function GuestApp({ app, startTab }: { app?: AppHandle; startTab?: string }) {
const reduce = useReducedMotion();
const [tab, setTab] = useState<Tab>(startTab === 'book' || startTab === 'mine' ? startTab : 'home');
const [today, setToday] = useState('');
const [nowMin, setNowMin] = useState(-1);
const [date, setDate] = useState('');
const [party, setParty] = useState(2);
const [slotId, setSlotId] = useState('');
const [note, setNote] = useState('');
const [busy, setBusy] = useState(false);
const [toast, setToast] = useState<{ kind: 'ok' | 'err'; text: string } | null>(null);
const [confirmed, setConfirmed] = useState<R | null>(null);
const [openQr, setOpenQr] = useState('');
const [askCancel, setAskCancel] = useState('');

useEffect(() => {
const d = new Date();
setToday(ymd(d));
setDate(ymd(d));
setNowMin(d.getHours() * 60 + d.getMinutes());
}, []);
useEffect(() => (app ? app.live('slot_load') : undefined), [app]);
useEffect(() => (app ? app.live('booking') : undefined), [app]);
useEffect(() => {
if (!toast) return;
const t = setTimeout(() => setToast(null), 4000);
return () => clearTimeout(t);
}, [toast]);

const dishes = app?.rows('dish') ?? [];
const slotsRaw = app?.rows('slot');
const slots = useMemo(() => [...(slotsRaw ?? [])].sort((a, b) => n(a.sort) - n(b.sort)), [slotsRaw]);
const loads = app?.rows('slot_load') ?? [];
const hoursRaw = app?.rows('opening_hour');
const hours = useMemo(() => [...(hoursRaw ?? [])].sort((a, b) => n(a.sort) - n(b.sort)), [hoursRaw]);
const bookings = app?.rows('booking') ?? [];
const loadingSlots = app ? app.loading('slot') : false;
const loadingDishes = app ? app.loading('dish') : false;
const loadingBookings = app ? app.loading('booking') : false;
